#include <bits/stdc++.h>
using namespace std;
struct DSU {
    vector<int> p;
    DSU(int n) : p(n) { iota(p.begin(), p.end(), 0); }
    int f(int x) { return p[x] == x ? x : p[x] = f(p[x]); }
    bool u(int a, int b) { a = f(a); b = f(b); if (a == b) return false; p[a] = b; return true; }
};
int main() {
    int n, m, D;
    scanf("%d %d %d", &n, &m, &D);
    vector<pair<int,int>> e(m);
    for (auto &x : e) scanf("%d %d", &x.first, &x.second);
    DSU d1(n + 1);
    vector<int> nb;
    for (auto [a, b] : e) {
        if (a == 1) nb.push_back(b);
        else if (b == 1) nb.push_back(a);
        else d1.u(a, b);
    }
    vector<char> seen(n + 1, 0), taken(n + 1, 0);
    vector<int> chosen;
    for (int v : nb) {
        int r = d1.f(v);
        if (!seen[r]) { seen[r] = 1; chosen.push_back(v); taken[v] = 1; }
    }
    int k = chosen.size(), c = nb.size();
    if (D < k || D > c) { puts("NO"); return 0; }
    for (int v : nb) if ((int)chosen.size() < D && !taken[v]) { chosen.push_back(v); taken[v] = 1; }
    DSU d2(n + 1);
    vector<pair<int,int>> out;
    for (int v : chosen) { d2.u(1, v); out.push_back({1, v}); }
    for (auto [a, b] : e) if (a != 1 && b != 1 && d2.u(a, b)) out.push_back({a, b});
    puts("YES");
    for (auto [a, b] : out) printf("%d %d\n", a, b);
}

