    long long best = LLONG_MAX; string bestS;
    for (int d = 0; d < 10; d++) {
        vector<int> idx(n);
        iota(idx.begin(), idx.end(), 0);
        auto cost = [&](int i) { return abs((s[i] - '0') - d); };
        sort(idx.begin(), idx.end(), [&](int x, int y) {
            if (cost(x) != cost(y)) return cost(x) < cost(y);
            bool gx = s[x] - '0' > d, gy = s[y] - '0' > d;
