    }
    printf("%lld\n%s\n", best, bestS.c_str());
}

#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1000000007LL;
long long pw(long long b, long long e) { long long r = 1; b %= MOD; while (e) { if (e & 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; } return r; }
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; long long p; scanf("%d %lld", &n, &p);
        vector<long long> k(n);
        for (auto &x : k) scanf("%lld", &x);
        if (p == 1) { printf("%d\n", n % 2); continue; }
        sort(k.rbegin(), k.rend());
        long long ans = 0, need = 0, cur = 0;
        bool big = false;
        for (int i = 0; i < n; i++) {
            long long rem = n - i, v = pw(p, k[i]);
            if (big) { ans = (ans - v + MOD) % MOD; continue; }
            if (need == 0) { need = 1; cur = k[i]; ans = (ans + v) % MOD; continue; }
            while (cur > k[i] && need <= rem) { need *= p; cur--; }
            if (cur > k[i] || need > rem) { big = true; ans = (ans - v + MOD) % MOD; continue; }
            need--; ans = (ans - v + MOD) % MOD;
        }
        printf("%lld\n", ans);
    }
}

