#include <bits/stdc++.h>
using namespace std;
static char s[200005], f[200005];
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n, q; scanf("%d %d %s %s", &n, &q, s, f);
        vector<pair<int,int>> qs(q);
        for (auto &x : qs) scanf("%d %d", &x.first, &x.second);
        map<int,int> mp;  // run start -> digit, sentinel at n+1
        mp[1] = f[0] - '0';
        for (int i = 1; i < n; i++) if (f[i] != f[i-1]) mp[i+1] = f[i] - '0';
        mp[n+1] = -1;
        auto split = [&](int x) { if (!mp.count(x)) mp[x] = prev(mp.upper_bound(x))->second; };
        bool ok = true;
        for (int i = q - 1; i >= 0 && ok; i--) {
            int l = qs[i].first, r = qs[i].second;
            split(l); split(r + 1);
            auto itl = mp.find(l);
            long long ones = 0, zeros = 0;
            for (auto it = itl; it->first <= r; ++it) {
                long long len = min(next(it)->first, r + 1) - it->first;
                (it->second ? ones : zeros) += len;
            }
            long long len = r - l + 1;
            if (ones * 2 > len) itl->second = 1;
            else if (zeros * 2 > len) itl->second = 0;
            else { ok = false; break; }
            mp.erase(next(itl), mp.find(r + 1));
        }
        if (ok)
            for (auto it = mp.begin(); it != prev(mp.end()) && ok; ++it)
                for (int p = it->first; p < next(it)->first; p++)
                    if (s[p-1] - '0' != it->second) { ok = false; break; }
        puts(ok ? "YES" : "NO");
    }
}

