typedef long long ll;
bool feasible(ll n, ll x, ll s) {
    __int128 sum = 0;
    ll cur = x;
    ll steps = min<ll>(n, 80);
    for (ll i = 0; i < steps; i++) { sum += cur; cur = (cur + 1) / 2; }
    sum += (__int128)(n - steps);
    return sum <= s;
}
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        ll n, s; scanf("%lld %lld", &n, &s);
        ll lo = 1, hi = s;
        while (lo < hi) {
            ll mid = lo + (hi - lo + 1) / 2;
            if (feasible(n, mid, s)) lo = mid; else hi = mid - 1;
        }
        printf("%lld\n", lo);
    }
}

