        for (auto &x : a) scanf("%lld", &x);
        for (auto &x : b) scanf("%lld", &x);
        vector<pair<int, ll>> st;   // (unrolled start index, remaining mass)
        int ans = 0;
        for (int p = 0; p < 2 * n; p++) {
            int j = p % n;
