#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int M, LOGM;
vector<ll> vals; vector<int> cntT; vector<ll> sumT;
void upd(int i, int dc, ll ds) { for (; i <= M; i += i & -i) { cntT[i] += dc; sumT[i] += ds; } }
ll smallestSum(int r) {  // sum of the r smallest inserted values
    int pos = 0; ll c = 0, s = 0;
    for (int pw = LOGM; pw; pw >>= 1)
        if (pos + pw <= M && c + cntT[pos + pw] <= r) { pos += pw; c += cntT[pos]; s += sumT[pos]; }
    if (c < r) s += (ll)(r - c) * vals[pos + 1];
    return s;
}
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n, m; scanf("%d %d", &n, &m);
        vector<ll> X(n); vector<int> Y(n), ord(n);
        for (int i = 0; i < n; i++) { scanf("%lld %d", &X[i], &Y[i]); ord[i] = i; }
        sort(ord.begin(), ord.end(), [&](int a, int b) { return X[a] < X[b]; });
        M = n; LOGM = 1; while (LOGM * 2 <= M) LOGM *= 2;
        vals.assign(M + 1, 0); cntT.assign(M + 1, 0); sumT.assign(M + 1, 0);
        vector<int> posOf(n);
        for (int r = 0; r < n; r++) { posOf[ord[r]] = r + 1; vals[r + 1] = X[ord[r]]; }
        vector<vector<int>> bucket(n + 2); for (int i = 0; i < n; i++) bucket[min(Y[i], n + 1)].push_back(i);
        vector<ll> D(n + 2, 0), PD(n + 2, LLONG_MIN / 4); vector<char> Dv(n + 2, 0);
        ll Smax = 0, total = 0; int cnt = 0;
        for (int k = n + 1; k >= 1; k--) {
            for (int i : bucket[k - 1]) { upd(posOf[i], 1, X[i]); cnt++; total += X[i]; }
            if (cnt >= k - 1) { Dv[k] = 1; D[k] = total - smallestSum(cnt - (k - 1)); }
            if (cnt >= k && k <= n) Smax = max(Smax, total - smallestSum(cnt - k));
        }
        for (int k = 1; k <= n + 1; k++) { PD[k] = PD[k - 1]; if (Dv[k]) PD[k] = max(PD[k], D[k]); }
        for (int j = 0; j < m; j++) {
            ll x0; int y0; scanf("%lld %d", &x0, &y0);
            printf("%lld%c", max(Smax, PD[min(y0 + 1, n + 1)] + x0), j + 1 < m ? ' ' : '\n');
        }
    }
}

