#include <bits/stdc++.h>
using namespace std;
const int NEG = -1000000;
int main() {
    int n; scanf("%d", &n);
    int N = 2 * n; vector<int> a(N);
    for (auto &x : a) scanf("%d", &x);
    int cnt[100] = {0};
    for (int x : a) cnt[x]++;
    vector<int> vals;
    for (int v = 10; v < 100; v++) if (cnt[v]) vals.push_back(v);
    int V = vals.size();  // dp[i][s][d1]: max distinct in heap 2; s cubes, d1 distinct in heap 1
    vector<vector<vector<int>>> dp(V + 1, vector<vector<int>>(n + 1, vector<int>(V + 1, NEG)));
    dp[0][0][0] = 0;
    for (int i = 0; i < V; i++) {
        int c = cnt[vals[i]];
        for (int s = 0; s <= n; s++) for (int d1 = 0; d1 <= V; d1++) if (dp[i][s][d1] != NEG)
            for (int k = 0; k <= c && s + k <= n; k++)
                dp[i+1][s+k][d1+(k>0)] = max(dp[i+1][s+k][d1+(k>0)], dp[i][s][d1] + (c - k > 0));
    }
    int bestP = -1, bestD1 = 0;
    for (int d1 = 0; d1 <= V; d1++)
        if (dp[V][n][d1] != NEG && d1 * dp[V][n][d1] > bestP) { bestP = d1 * dp[V][n][d1]; bestD1 = d1; }
    vector<int> kv(V, 0);
    int s = n, d1 = bestD1;
    for (int i = V - 1; i >= 0; i--) {
        int c = cnt[vals[i]];
        for (int k = 0; k <= c && s - k >= 0; k++) {
            int ps = s - k, pd = d1 - (k > 0);
            if (pd >= 0 && dp[i][ps][pd] != NEG && dp[i][ps][pd] + (c - k > 0) == dp[i+1][s][d1]) {
                kv[i] = k; s = ps; d1 = pd; break;
            }
        }
