#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int n, m; ll S;
vector<ll> a, b, c;
vector<int> bugOrd, stOrd;
bool check(int D, vector<int> *out) {
    int blocks = (m + D - 1) / D, sp = 0;
    priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;
    ll total = 0;
    vector<int> chosen(blocks);
    for (int j = 0; j < blocks; j++) {
        ll req = a[bugOrd[j * D]];
        while (sp < n && b[stOrd[sp]] >= req) { pq.push({c[stOrd[sp]], stOrd[sp]}); sp++; }
        if (pq.empty()) return false;
        total += pq.top().first; chosen[j] = pq.top().second; pq.pop();
        if (total > S) return false;
    }
    if (out) for (int j = 0; j < blocks; j++)
        for (int q = j * D; q < min(m, (j + 1) * D); q++) (*out)[bugOrd[q]] = chosen[j] + 1;
    return true;
}
int main() {
    scanf("%d %d %lld", &n, &m, &S);
    a.resize(m); b.resize(n); c.resize(n);
    for (auto &x : a) scanf("%lld", &x);
    for (auto &x : b) scanf("%lld", &x);
    for (auto &x : c) scanf("%lld", &x);
    bugOrd.resize(m); iota(bugOrd.begin(), bugOrd.end(), 0);
    sort(bugOrd.begin(), bugOrd.end(), [&](int x, int y) { return a[x] > a[y]; });
    stOrd.resize(n); iota(stOrd.begin(), stOrd.end(), 0);
    sort(stOrd.begin(), stOrd.end(), [&](int x, int y) { return b[x] > b[y]; });
    if (!check(m, nullptr)) { puts("NO"); return 0; }
    int lo = 1, hi = m;
    while (lo < hi) { int mid = (lo + hi) / 2; if (check(mid, nullptr)) hi = mid; else lo = mid + 1; }
    vector<int> out(m); check(lo, &out);
    printf("YES\n");
    for (int x : out) printf("%d ", x);
    printf("\n");
}

