#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main() {
    int m, n; scanf("%d %d", &m, &n);
    vector<ll> a(m), b(n);
    ll SA = 0, SB = 0;
    for (auto &x : a) { scanf("%lld", &x); SA += x; }
    for (auto &x : b) { scanf("%lld", &x); SB += x; }
    sort(a.rbegin(), a.rend());
    sort(b.rbegin(), b.rend());
    __int128 best = -1;
    auto upd = [&](__int128 v) { if (best < 0 || v < best) best = v; };
    ll pa = 0;
    for (int k = 1; k <= m; k++) { pa += a[k - 1]; upd((__int128)(SA - pa) + (__int128)k * SB); }
    ll pb = 0;
    for (int k = 1; k <= n; k++) { pb += b[k - 1]; upd((__int128)(SB - pb) + (__int128)k * SA); }
    printf("%lld\n", (ll)best);
}

